return {
  json: {
    property_id: payload.property_id || '',
    guest_name: String(payload.guest_name || '').trim(),
    guest_email: String(payload.guest_email || '').toLowerCase().trim(),
    check_in: payload.check_in || '',
    check_out: payload.check_out || '',
    guest_count: Number(payload.guest_count || 1),
    rental_purpose: String(payload.rental_purpose || '').trim()
  }
};

// 1. Retrieve booking request payload and property context
const item = $('2. Payload Schema Validation').first().json;

const guestName = item.guest_name || 'Guest';
const guestEmail = item.guest_email || '';
const guestCount = Number(item.guest_count || 0);
const propertyCapacity = Number($input.first().json.Capacity || 0);
const rentalPurpose = (item.rental_purpose || '').toLowerCase();

// 2. Define risk rules and configuration
const restrictedKeywords = ["party", "birthday", "wedding", "rave", "smoking", "bachelor", "bachelorette", "event"];
let riskSignals = [];
let reasoningParts = [];
let riskScore = 0;

// --- HARD CHECK 1: Capacity Limit Violation ---
if (guestCount > propertyCapacity) {
  riskSignals.push("GUEST_COUNT_EXCEEDS_CAPACITY");
  reasoningParts.push(`Requested guest count (${guestCount}) exceeds property max capacity (${propertyCapacity}).`);
  riskScore += 90; // Immediate High Risk
}

// --- HARD CHECK 2: Restricted Purpose Keyword Match ---
const foundKeywords = restrictedKeywords.filter(keyword => rentalPurpose.includes(keyword));
if (foundKeywords.length > 0) {
  riskSignals.push("PROHIBITED_PURPOSE_KEYWORD");
  reasoningParts.push(`Stated purpose contains prohibited keywords: [${foundKeywords.join(", ")}].`);
  riskScore += 85; // Immediate High Risk
}

// --- SOFT CHECK 3: High Capacity Usage (> 90% Capacity) ---
if (propertyCapacity > 0 && (guestCount / propertyCapacity) >= 0.9 && guestCount > 1) {
  if (!riskSignals.includes("GUEST_COUNT_EXCEEDS_CAPACITY")) {
    riskSignals.push("HIGH_CAPACITY_UTILIZATION");
    reasoningParts.push(`Booking size (${guestCount}) is at or near maximum capacity (${propertyCapacity}).`);
    riskScore += 25;
  }
}

// --- SOFT CHECK 4: Vague or Short Rental Purpose ---
if (rentalPurpose.length < 5) {
  riskSignals.push("VAGUE_RENTAL_PURPOSE");
  reasoningParts.push("Stated rental purpose is unusually brief or missing details.");
  riskScore += 20;
}

// 3. Final Risk Determination
// Cap total score between 0 and 100
const finalRiskScore = Math.min(Math.max(riskScore, 0), 100);

// Set risk level strictly to HIGH or LOW based on score threshold (>= 50 is HIGH)
const riskLevel = finalRiskScore >= 50 ? "HIGH" : "LOW";
const recommendation = riskLevel === "HIGH" ? "manual_review" : "auto_approve";
const finalReasoning = reasoningParts.length > 0 
  ? reasoningParts.join(" ") 
  : "Standard booking within normal operating parameters.";

// 4. Return formatted response for downstream nodes (Airtable & Switch/IF node)
return {
  json: {
    booking_record_id: item.booking_record_id || item.id || '',
    booking_id: item.booking_id || '',
    guest_name: guestName,
    guest_email: guestEmail,
    guest_count: guestCount,
    property_capacity: propertyCapacity,
    rental_purpose: item.rental_purpose || '',
    risk_score: finalRiskScore,
    risk_level: riskLevel, // Output: "HIGH" or "LOW"
    risk_signals: riskSignals.length > 0 ? riskSignals.join(", ") : "NONE",
    ai_reasoning: finalReasoning,
    recommendation: recommendation,
    is_high_risk: riskLevel === "HIGH"
  }
};

